'use strict';
const $=id=>document.getElementById(id);
const M=window.RainModel, model=M.createModel(window.RAIN_DATA);
const state={preset:'summer-autumn',expanded:false,year:null};
let current;
const pct=x=>x==null?'—':Math.round(x*100)+' %';
const anomaly=x=>(x>=0?'+':'−')+Math.abs(x).toFixed(0)+' %';
const fmt=x=>Math.round(x).toLocaleString('nb-NO');
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rangeText=(start,length)=>M.MONTHS[start-1]+'–'+M.MONTHS[(start+length-2)%12]+' · '+length+' mnd.';
M.MONTHS.forEach((m,i)=>$('startMonth').add(new Option(m,i+1)));$('startMonth').value='6';
function config(){return {...(state.preset==='custom'?{start:+$('startMonth').value,length:+$('length').value,gap:+$('gap').value,target:+$('targetLength').value,second:0,first:'Våt periode',last:'Perioden etterpå',outcome:'av periodene var tørrere enn normalt'}:M.presets[state.preset]),threshold:+$('threshold').value,from:+$('from').value,reference:$('reference').value}}
function choose(p){if(p!=='custom'&&!M.presets[p])throw Error('Ukjent hypotese');state.preset=p;state.year=null;state.expanded=false;document.querySelectorAll('.preset').forEach(b=>{b.classList.toggle('selected',b.dataset.preset===p);b.setAttribute('aria-pressed',b.dataset.preset===p)});$('customControls').hidden=p!=='custom';render()}
function flow(c){let parts=[{name:c.first,description:rangeText(c.start,c.length)}];if(c.second)parts.push({name:'Også våt vinter',description:'Des–Feb · eget vilkår'});if(c.gap)parts.push({name:'Ventetid',description:c.gap+' måneder',class:'gap'});parts.push({name:c.last,description:rangeText((c.start+c.length+c.second+c.gap-1)%12+1,c.target),class:'target'});$('flowSteps').innerHTML=parts.map((p,i)=>(i?'<span class="flow-separator" aria-hidden="true">›</span>':'')+`<div class="flow-item ${p.class||''}"><strong>${p.name}</strong><span>${p.description}</span></div>`).join('')}
function trajectory(){const r=current,chosen=r.matches.find(x=>x.year===state.year),seq=chosen?chosen.sequence:r.sequence;let title=chosen?'Forløpet som startet i '+chosen.year:'Det gjennomsnittlige forløpet';$('trajectoryTitle').textContent=title;$('trajectorySubtitle').textContent=chosen?'Faktisk månedsnedbør mot normalen ved valgt forløp':'Månedlige avvik i de '+r.n+' historiske treffene';
 if(!seq.length){$('trajectoryChart').innerHTML='<p class="muted">Ingen komplette forløp passer disse valgene. Prøv en lavere terskel eller mer historikk.</p>';$('trajectoryNote').textContent='Et tomt utvalg betyr ikke 0 % sannsynlighet.';return}
 const W=720,H=220,p={l:45,r:12,t:27,b:42},cw=W-p.l-p.r,ch=H-p.t-p.b;const bound=Math.max(60,Math.ceil(Math.max(...seq.map(x=>Math.abs(x.value)))/25)*25),y=v=>p.t+(bound-v)/(bound*2)*ch,step=cw/seq.length,targetAt=r.config.length+r.config.second+r.config.gap;
 let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Månedlige nedbøravvik ${escape(title)}">`;
 svg+=`<rect x="${p.l+targetAt*step}" y="8" width="${r.config.target*step}" height="${H-24}" fill="#fbf5eb" rx="5"/><text x="${p.l+targetAt*step+5}" y="21" font-size="10" fill="#9e783f">UTFALLET</text>`;
 for(const v of [-bound,0,bound])svg+=`<line x1="${p.l}" x2="${W-p.r}" y1="${y(v)}" y2="${y(v)}" stroke="${v===0?'#a9bcc2':'#e7eeee'}"/><text x="${p.l-8}" y="${y(v)+4}" text-anchor="end" font-size="11" fill="#70838c">${v>0?'+':''}${v}%</text>`;
 seq.forEach((s,i)=>{const x=p.l+i*step+step*.15,h=Math.abs(y(s.value)-y(0));svg+=`<rect x="${x}" y="${Math.min(y(s.value),y(0))}" width="${step*.7}" height="${Math.max(h,.5)}" rx="2" fill="${s.value>=0?'#148b80':'#d7a15b'}"><title>${escape(s.label)}: ${anomaly(s.value)}</title></rect>`;if(seq.length<=18||i%3===0)svg+=`<text x="${x+step*.35}" y="${H-17}" text-anchor="middle" font-size="11" fill="#6f838b">${M.MONTHS[s.month]}</text>`});
 $('trajectoryChart').innerHTML=svg+'</svg>';$('trajectoryNote').innerHTML=chosen?`Totalt etterpå: <strong>${fmt(chosen.target.actual)} mm</strong> mot ${fmt(chosen.target.normal)} mm normalt. <button class="text-button" id="resetYear">Vis gjennomsnittet</button>`:`Gjennomsnittlig samlet avvik etterpå: <strong>${anomaly(r.meanOutcome)}</strong>. Stolpene viser måneder; hypotesen vurderer hele perioder.`;if($('resetYear'))$('resetYear').onclick=()=>{state.year=null;trajectory()};
}
function rows(){const rs=[...current.matches],sort=$('sort').value;rs.sort(sort==='wettest'?(a,b)=>b.first.anomaly-a.first.anomaly:sort==='driest'?(a,b)=>a.target.anomaly-b.target.anomaly:(a,b)=>b.year-a.year);const shown=state.expanded?rs:rs.slice(0,7);$('matchesTitle').textContent=current.n+' år passer hypotesen';$('secondHeading').textContent=current.config.second?'Vinteren også våt':'Ekstra vilkår';$('matchRows').innerHTML=shown.length?shown.map(r=>`<tr><td><button data-year="${r.year}" aria-label="Vis forløpet som starter ${r.year}">${r.year}</button><div class="small muted">${M.label(r.first.start)}</div></td><td><strong class="positive">${anomaly(r.first.anomaly)}</strong><div class="small muted">${fmt(r.first.actual)} mm</div></td><td>${r.second?`<span class="positive">${anomaly(r.second.anomaly)}</span>`:'—'}</td><td><strong class="${r.target.anomaly>=0?'positive':'negative'}">${anomaly(r.target.anomaly)}</strong><div class="small muted">${M.label(r.target.start)} – ${M.label(r.target.end)}</div></td><td><span class="badge ${r.dry?'':'wet'}">${r.dry?'Tørrere':'Våtere / likt'}</span></td></tr>`).join(''):'<tr><td colspan="5">Ingen treff. Senk terskelen eller utvid historikken.</td></tr>';$('showMore').hidden=rs.length<=7;$('showMore').textContent=state.expanded?'Vis færre':'Vis alle '+rs.length+' treff';document.querySelectorAll('[data-year]').forEach(b=>b.onclick=()=>{state.year=+b.dataset.year;trajectory();$('trajectoryTitle').scrollIntoView({behavior:'smooth',block:'center'})});
 const split=current.splits.map(s=>`<strong>${s.name}:</strong> ${pct(s.p)} tørre utfall (${s.n} treff)`).join(' &nbsp; · &nbsp; ');$('validation').innerHTML=split+'<br>Dette er en stabilitetssjekk mellom tidsperioder, ikke en uavhengig prognosetest. Endrer du hypotesen etter å ha sett resultatet, må den testes på nye data.';
}
function render(){const c=config();current=model.analyze(c);const r=current;$('thresholdValue').textContent=c.threshold+' % over normalen';$('outcomeTitle').textContent=c.outcome;$('probability').textContent=pct(r.probability);$('counts').textContent=r.n?`${r.dry} av ${r.n} treff · ${r.eligible.length} komplette forløp undersøkt`:'Ingen treff med disse valgene';$('probFill').style.width=(r.probability==null?0:r.probability*100)+'%';$('baseline').textContent='Uten krav om våt periode: '+pct(r.baseline);const diff=r.probability==null?null:(r.probability-r.baseline)*100;$('difference').textContent=diff==null?'—':`${diff>=0?'+':'−'}${Math.abs(diff).toFixed(1)} prosentpoeng`;$('interval').textContent=r.n?`95 % Wilson-intervall: ${pct(r.interval[0])}–${pct(r.interval[1])}`:'Usikkerhet kan ikke beregnes';$('strength').textContent=r.n<10?'Få treff · stor usikkerhet':'Utforskende funn · ikke et varsel';$('referenceNote').textContent=c.reference==='trailing'?'Normalen fryses før hvert forløp. Minst 20 tidligere år kreves.':'Beskrivende normal. Inneholder fremtidige målinger for eldre forløp.';flow(c);trajectory();rows()}
function history(){const seq=model.history(),W=1120,H=230,p={l:45,r:12,t:16,b:35},cw=W-p.l-p.r,ch=H-p.t-p.b,max=80,y=v=>p.t+(max-v)/(max*2)*ch;let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Rullerende 12 måneders nedbøravvik fra 1890 til 2026">`;for(const v of [-50,0,50])svg+=`<line x1="${p.l}" x2="${W-p.r}" y1="${y(v)}" y2="${y(v)}" stroke="#d9e4e6"/><text x="${p.l-7}" y="${y(v)+4}" text-anchor="end" fill="#71868e" font-size="11">${v>0?'+':''}${v}%</text>`;seq.forEach((s,i)=>{const x=p.l+i/seq.length*cw;svg+=`<rect x="${x}" y="${Math.min(y(s.value),y(0))}" width="${cw/seq.length+.15}" height="${Math.abs(y(s.value)-y(0))}" fill="${s.value>=0?'#188e84':'#d7a15b'}"><title>${s.label}: ${anomaly(s.value)}</title></rect>`;const d=M.date(s.index);if(d.month===1&&d.year%20===0)svg+=`<text x="${x}" y="${H-9}" text-anchor="middle" font-size="12" fill="#71868e">${d.year}</text>`});$('historyChart').innerHTML=svg+'</svg>'}
document.querySelectorAll('.preset').forEach(b=>b.onclick=()=>choose(b.dataset.preset));['threshold','from','reference','startMonth','length','gap','targetLength'].forEach(id=>$(id).addEventListener(id==='threshold'?'input':'change',()=>{state.year=null;state.expanded=false;render()}));$('sort').onchange=rows;$('showMore').onclick=()=>{state.expanded=!state.expanded;rows()};choose(state.preset);history();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'configure_rainfall_hypothesis',title:'Utforsk en nedbørhypotese',description:'Velg et sesongforløp og en våthetsterskel i Regnrytme. Returnerer historiske treff og frekvens, ikke et fremtidsvarsel.',inputSchema:{type:'object',properties:{preset:{type:'string',enum:Object.keys(M.presets)},threshold:{type:'number',minimum:0,maximum:60}},required:['preset','threshold'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!M.presets[input.preset]||!Number.isFinite(input.threshold)||input.threshold<0||input.threshold>60||input.threshold%5!==0)throw Error('Velg en kjent hypotese og terskel 0–60 i trinn på 5.');$('threshold').value=String(input.threshold);choose(input.preset);return {matches:current.n,dryCount:current.dry,historicalDryFraction:current.probability,baseline:current.baseline}}})).catch(()=>{})}catch{}}
